def derive_statuses(apps, schema_editor):
    """
    Re-derive every invoice's status under the new rule.

    SalesInvoice.display_status is the authority for this rule; it cannot be
    called here because apps.get_model returns a historical model with no
    properties, and a migration must not import sales.models. So the rule is
    re-expressed in ORM terms and the two have to be kept in step - there is
    no way around the duplication.

    Cancelled is never touched: it is the one status a person sets.

    Overdue is deliberately not derived here. It depends on what the khaata
    has settled onto an invoice, which accounts/settlement.py works out on
    read and stores nowhere, and it changes when the date rolls over - so any
    value written now would be wrong by tomorrow. It is produced on read.
    """
    SalesInvoice = apps.get_model('sales', 'SalesInvoice')
    alias = schema_editor.connection.alias
    live = SalesInvoice.objects.using(alias).exclude(status='X')

    # Materialised rather than filtered with a reverse-FK join: that join
    # yields one row per item, and a joined .update() is a subquery rewrite on
    # some backends and an error on others. The row count here is small.
    empty = list(
        live.filter(invoice_items__isnull=True)
        .values_list('pk', flat=True)
        .distinct()
    )

    drafted = live.filter(pk__in=empty).update(status='D')
    completed = live.exclude(pk__in=empty).update(status='C')
    print(f"\n    statuses re-derived: {drafted} -> Draft, {completed} -> Completed")


def repair_item_deduction_flags(apps, schema_editor):
    """
    Repair lines the old flag got wrong.

    update_restock_flags used to read quantity_received, which the sales
    update path never set, so a line could be fully deducted in the ledger and
    still be flagged otherwise. Only such lines are touched.

    Deliberately NOT a blanket backfill from the ledger. Most items carry
    is_deducted with an EMPTY ledger - the migrated Ebrahim Traders invoices,
    flagged that way precisely so that importing them moved no stock. Resetting
    those would make every one of them deduct on its next edit.
    """
    SalesInvoiceItem = apps.get_model('sales', 'SalesInvoiceItem')
    alias = schema_editor.connection.alias

    repaired = 0
    candidates = (
        SalesInvoiceItem.objects.using(alias)
        .filter(is_deducted=False)
        .annotate(deducted=Sum('restocks__quantity'))
        .filter(deducted__gt=0)
    )
    for item in candidates:
        if item.deducted >= item.quantity:
            SalesInvoiceItem.objects.using(alias).filter(pk=item.pk).update(
                is_deducted=True)
            repaired += 1
    print(f"    item deduction flags repaired from the ledger: {repaired}")


